// ActivepiecesのTypeScriptベースのカスタムアクション定義
import { createAction, Property } from "@activepieces/pieces-framework";
export const sendLootAlert = createAction({
  name: "send_loot_alert",
  displayName: "Send Loot Alert",
  props: { message: Property.ShortText({ displayName: "Alert Message", required: true }) },
  async run(context) { return { status: "DISPATCHED", payload: context.propsValue.message }; }
});
